import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {createDecoder} from '../stream-framer.js';

const done = 'data: [DONE]\n\n';
function decode(chunks) {
  const decoder = createDecoder();
  const frames = chunks.flatMap(chunk => decoder.push(chunk));
  assert.deepEqual(decoder.finish(), []);
  return frames;
}
function poisoned(decoder) {
  assert.throws(() => decoder.push(new Uint8Array()), Error);
  assert.throws(() => decoder.finish(), Error);
}

test('all split positions and bytewise input preserve exact fields and BOMs', () => {
  const bytes = Buffer.from('\uFEFFevent: forgotten\n: comment\nunknown: x\n\n' +
    'event: first\nevent: \ndata:  雪😀\rX\r\r\ndata:\uFEFFz\n\n' +
    'Data: ignored\ndata\n\nevent: stop\n' + done + '\r\n\n');
  const original = Buffer.from(bytes);
  const expected = [{event: 'message', data: ' 雪😀\rX\r\n\uFEFFz'}, {event: 'message', data: ''}];
  for (let i = 0; i <= bytes.length; i++) {
    assert.deepEqual(decode([bytes.subarray(0, i), Buffer.alloc(0), bytes.subarray(i)]), expected);
  }
  assert.deepEqual(decode([...bytes].map(byte => Uint8Array.of(byte))), expected);
  assert.deepEqual(bytes, original);
});

test('only exact joined DONE terminates and event fields reset', () => {
  assert.deepEqual(decode([Buffer.from('event: named\ndata: [DONE]\ndata: \n\n' +
    'data: [DONE] \n\nevent\n\ndata: ok\n\n' + done)]), [
    {event: 'named', data: '[DONE]\n'},
    {event: 'message', data: '[DONE] '},
    {event: 'message', data: 'ok'},
  ]);
});

test('invalid types and UTF-8 poison only their decoder', () => {
  for (const invalid of ['text', null, undefined, [], new ArrayBuffer(0), new Uint16Array(0),
    Buffer.from([0xff]), Buffer.from([0xc0, 0xaf]), Buffer.from([0xed, 0xa0, 0x80]),
    Buffer.from([0xf4, 0x90, 0x80, 0x80])]) {
    const decoder = createDecoder();
    assert.throws(() => decoder.push(invalid), Error);
    poisoned(decoder);
  }
  const decoder = createDecoder();
  decoder.push(Buffer.from([0xe2]));
  assert.throws(() => decoder.push(Buffer.from([0x28])), Error);
  poisoned(decoder);
  assert.deepEqual(decode([Buffer.from(done)]), []);
});

test('finish requires complete lines, complete UTF-8, and termination', () => {
  for (const input of ['', 'data: x\n\n', 'data: [DONE]\n', 'data: [DONE]',
    done + '\r', done + 'x', done + 'event: x', done + '\uFEFF']) {
    const decoder = createDecoder();
    decoder.push(Buffer.from(input));
    assert.throws(() => decoder.finish(), Error);
    poisoned(decoder);
  }
  const decoder = createDecoder();
  decoder.push(Buffer.from(done));
  decoder.push(Buffer.from([0xf0, 0x9f]));
  assert.throws(() => decoder.finish(), Error);
  poisoned(decoder);
  const finished = createDecoder();
  finished.push(Buffer.from(done));
  finished.finish();
  assert.throws(() => finished.finish(), Error);
  poisoned(finished);
});

test('every nonblank line after DONE fails, preserving previously returned frames', () => {
  for (const suffix of [done, ': comment\n', 'unknown\n', 'event\n', ' \n', '\r\r\n']) {
    const decoder = createDecoder();
    const previous = decoder.push(Buffer.from('data: earlier\n\n'));
    assert.throws(() => decoder.push(Buffer.from('data: unreturned\n\n' + done + suffix)), Error);
    assert.deepEqual(previous, [{event: 'message', data: 'earlier'}]);
    poisoned(decoder);
  }
});

const cli = fileURLToPath(new URL('../stream-framer.js', import.meta.url));
test('CLI validates arguments, JSON, UTF-8, base64 and protocol without partial stdout', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'stream-framer-'));
  const file = path.join(dir, 'input.json');
  const run = args => spawnSync(process.execPath, [cli, ...args], {encoding: 'utf8'});
  const rejected = result => {
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0);
  };
  try {
    rejected(run([]));
    rejected(run([file, 'extra']));
    rejected(run([file]));
    for (const input of [null, [], 1, 'string', {}, {chunks: null}, {chunks: 'abc'},
      ...[1, null, 'Zg', 'Zg=', 'Zh==', 'Zm9=', 'Zg===', ' Zg==', 'Zg==\n', '-w==', '_w==']
        .map(value => ({chunks: [value]})),
      {chunks: [Buffer.from('data: already emitted\n\n').toString('base64')]},
      {chunks: [Buffer.from(done + ': forbidden\n').toString('base64')]}]) {
      fs.writeFileSync(file, JSON.stringify(input));
      rejected(run([file]));
    }
    for (const invalid of [Buffer.from('{'), Buffer.from([0x22, 0xff, 0x22])]) {
      fs.writeFileSync(file, invalid);
      rejected(run([file]));
    }
    fs.writeFileSync(file, JSON.stringify({extra: true, chunks: ['', ...[...Buffer.from('data: 雪\n\n' + done)]
      .map(byte => Buffer.from([byte]).toString('base64'))]}));
    const result = run([file]);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, '{"frames":[{"event":"message","data":"雪"}]}\n');
  } finally {
    fs.rmSync(dir, {recursive: true, force: true});
  }
});

